# â”€â”€â”€ ط´ط¹ط§ط± ط§ظ„ظ…ظˆظ‚ط¹ (ظٹظڈط¶ظ…ظژظ‘ظ† ظƒظ€ base64 ظ„ط£ظ† ظ…ط¬ظ„ط¯ assets ظ„ط§ ظٹظڈط®ط¯ظژظ‘ظ… ط¹ط¨ط± ط§ظ„ظˆظٹط¨) â”€â”€â”€â”€â”€â”€
@st.cache_data(show_spinner=False)
def _logo_uri(name: str) -> str:
    path = os.path.join(os.path.dirname(__file__), "assets", name)
    mime = "image/jpeg" if name.lower().endswith((".jpg", ".jpeg")) else "image/png"
    try:
        with open(path, "rb") as f:
            return f"data:{mime};base64," + base64.b64encode(f.read()).decode()
    except OSError:
        return ""


