_POPULAR_LABEL = next(
    (lbl for key, _e, lbl, _k in _CATEGORY_RULES if key == "popular"), "ط´ط¹ط¨ظٹ"
)


def _food_category(name: str):
    """ط¥ط±ط¬ط§ط¹ (ظ…ظپطھط§ط­ ط§ظ„ظپط¦ط©طŒ ط§ط³ظ… ط§ظ„ظپط¦ط©) ظ„طµظ†ظپ ظ…ظ† ط§ط³ظ…ظ‡طŒ ط£ظˆ ('other','ط£ط®ط±ظ‰') ط¹ظ†ط¯ ط¹ط¯ظ… ط§ظ„طھط·ط§ط¨ظ‚."""
    n = _normalize(name)
    full = _CAT_SEP.sub(' ', n)
    toks = [t for t in full.split() if t]
    if "ط¨ط·ط§ط·ط³" in toks and any("ظ…ظ‚ظ„ظٹ" in t for t in toks):
        return ("fastfood", "ظˆط¬ط¨ط§طھ ط³ط±ظٹط¹ط©")
    for key, _emoji, label, kws in _CATEGORY_RULES:
        for kw in kws:
            if _cat_match(_normalize(kw), full, toks):
                return (key, label)
    return ("other", "ط£ط®ط±ظ‰")


def _resolve_category(row):
    """طھطµظ†ظٹظپ ط§ظ„طµظ†ظپ ظ…ظ† ط¹ظ…ظˆط¯ ط§ظ„ظپط¦ط© ظپظٹ Google Sheets: ط£ظٹ ظ‚ظٹظ…ط© ظپط¦ط© ظ…ظƒطھظˆط¨ط© ظپظٹ ط§ظ„ط¬ط¯ظˆظ„
    طھظڈط¹طھظ…ط¯ طھظ„ظ‚ط§ط¦ظٹط§ظ‹ ظˆطھط¸ظ‡ط± ظƒط´ط±ظٹط­ط© ظپظٹ ط§ظ„ط´ط±ظٹط· ط¯ظˆظ† ط£ظٹ طھط¹ط¯ظٹظ„ ظپظٹ ط§ظ„ظƒظˆط¯. آ«ط´ط¹ط¨ظٹآ» طھط¨ظ‚ظ‰
    ظ…ط±طھط¨ط·ط© ط¨ظ‚ط³ظ… آ«ط´ط¹ط¨ظٹآ»طŒ ظˆط£ظٹ ظ‚ظٹظ…ط© طھط·ط§ط¨ظ‚ ط§ط³ظ… ظپط¦ط© ظ…ط¹ط±ظˆظپط© طھظ†ط¯ظ…ط¬ ظ…ط¹ظ‡ط§طŒ ظˆط¥ظ„ط§ طھظڈظ†ط´ط£ ظپط¦ط©
    ط¬ط¯ظٹط¯ط© ط¨ط§ط³ظ…ظ‡ط§ ظƒظ…ط§ ظ‡ظˆ. ط¹ظ†ط¯ ط®ظ„ظˆظ‘ ط®ط§ظ†ط© ط§ظ„ظپط¦ط© ظ†ط±ط¬ط¹ ظ„ظ„طھطµظ†ظٹظپ ط­ط³ط¨ ط§ط³ظ… ط§ظ„طµظ†ظپ."""
    raw = str(row.get("cat_sheet", "")).strip()
    if raw and raw.lower() not in ("nan", "none"):
        norm = _normalize(raw)
        if "ط´ط¹ط¨ظٹ" in norm:
            return ("popular", _POPULAR_LABEL)
        known = _SHEET_LABEL_TO_CAT.get(norm)
        if known:
            return known
        return ("sheet:" + norm, _to_western(raw))
    return _food_category(str(row.get("name", "")))


_DEDUP_INVISIBLE = re.compile(r'[\u200b-\u200f\u202a-\u202e\u0640\ufeff]')
_DEDUP_WS = re.compile(r'\s+')

# ط®ط±ظٹط·ط©: ط§ط³ظ… ظپط¦ط© ظ…ظƒطھظˆط¨ ظپظٹ ط§ظ„ط¬ط¯ظˆظ„ (ظ…ط·ط¨ظژظ‘ط¹) â†’ (ظ…ظپطھط§ط­طŒ طھط³ظ…ظٹط©) ظ„ط¥ط­ط¯ظ‰ ط§ظ„ظ‚ظˆط§ط¹ط¯ ط§ظ„ط«ط§ط¨طھط©طŒ
# ط­طھظ‰ ظ„ظˆ ظƒطھط¨ ط§ظ„ظ…ط³طھط®ط¯ظ… ظپظٹ ط§ظ„ط¬ط¯ظˆظ„ آ«ط­ظ„ظˆظٹط§طھآ» طھظ†ط¯ظ…ط¬ ظ…ط¹ ظپط¦ط© ط§ظ„ط­ظ„ظˆظٹط§طھ ط¨ط¯ظ„ ط¥ظ†ط´ط§ط، ظپط¦ط© ظ…ظƒط±ط±ط©.
# طھظڈط¹ط±ظژظ‘ظپ ط¨ط¹ط¯ _DEDUP_INVISIBLE ظ„ط£ظ† _normalize ظٹط³طھط®ط¯ظ…ظ‡ ط¹ظ†ط¯ ط¨ظ†ط§ط، ظ‡ط°ظ‡ ط§ظ„ط®ط±ظٹط·ط© ظˆظ‚طھ ط§ظ„ط§ط³طھظٹط±ط§ط¯.
_SHEET_LABEL_TO_CAT = {
    _normalize(lbl): (key, lbl) for key, _e, lbl, _kw in _CATEGORY_RULES
}

def _dedup_norm(s):
    """ظ…ظپطھط§ط­ ظ…ظ‚ط§ط±ظ†ط© ظ…ظˆط­ظ‘ط¯: ط¥ط²ط§ظ„ط© ط§ظ„ط±ظ…ظˆط² ط؛ظٹط± ط§ظ„ظ…ط±ط¦ظٹط© (ط§ظ„ظ…ط³ط§ظپط§طھ ط§ظ„طµظپط±ظٹط©/ط¹ظ„ط§ظ…ط§طھ ط§ظ„ط§طھط¬ط§ظ‡/
    ط§ظ„طھط·ظˆظٹظ„ ظ€) ظˆط¯ظ…ط¬ ط§ظ„ظ…ط³ط§ظپط§طھ ط§ظ„ظ…طھظƒط±ط±ط© ظپظٹ ظ…ط³ط§ظپط© ظˆط§ط­ط¯ط©طŒ ط­طھظ‰ طھظڈط¹طھط¨ط± ط§ظ„ظ‚ظٹظ… ط§ظ„ظ…طھط·ط§ط¨ظ‚ط©
    ط¨طµط±ظٹط§ظ‹ ظ…طھط·ط§ط¨ظ‚ط©. ظ„ط§ ظٹط؛ظٹظ‘ط± ط§ظ„ظ†طµ ط§ظ„ظ…ط¹ط±ظˆط¶ â€” ظٹظڈط³طھط®ط¯ظ… ظ„ظ„ظ…ظ‚ط§ط±ظ†ط© ظپظ‚ط·."""
    s = _DEDUP_INVISIBLE.sub('', str(s))
    return _DEDUP_WS.sub(' ', s).strip()

def _dedup_records(records):
    """ط¥ط²ط§ظ„ط© ط§ظ„طھظƒط±ط§ط± ط¯ط§ط®ظ„ ط§ظ„ظ‚ط³ظ… ط§ظ„ظˆط§ط­ط¯: ظ„ط§ ظٹظڈط­ط°ظپ ط³ط¬ظ„ ط¥ظ„ط§ ط¥ط°ط§ طھط·ط§ط¨ظ‚طھ ط¬ظ…ظٹط¹ ط¨ظٹط§ظ†ط§طھظ‡
    ط§ظ„ط£ط³ط§ط³ظٹط© (ط§ظ„ط§ط³ظ… + ط§ظ„ظƒظ…ظٹط© + ظ‚ظٹظ…ط© ط§ظ„ظƒط±ط¨ظˆظ‡ظٹط¯ط±ط§طھ)طŒ ظˆظٹظڈط¨ظ‚ظ‰ ط£ظˆظ„ ط¸ظ‡ظˆط± ظپظ‚ط·. طھظڈظ‡ظ…ظژظ„ ظپط±ظˆظ‚
    ط§ظ„ظ…ط³ط§ظپط§طھ/ط§ظ„ط±ظ…ظˆط² ط؛ظٹط± ط§ظ„ظ…ط±ط¦ظٹط© ظˆط­ط¯ظ‡ط§ط› ط£ظٹ ط§ط®طھظ„ط§ظپ ط­ظ‚ظٹظ‚ظٹ ظپظٹ ط§ظ„ط§ط³ظ… ط£ظˆ ط§ظ„ظƒظ…ظٹط© ط£ظˆ ظ‚ظٹظ…ط©
    ط§ظ„ظƒط±ط¨ظˆظ‡ظٹط¯ط±ط§طھ ظٹط¨ظ‚ظ‰ ط³ط¬ظ„ط§ظ‹ ظ…ظ†ظپطµظ„ط§ظ‹. ظ„ط§ ظٹظڈط­ط°ظپ ط£ظٹ طµظپ ظ…ظ† Google Sheets ظ†ظپط³ظ‡."""
    seen = set()
    out = []
    for r in records:
        key = (_dedup_norm(r.get("name", "")),
               _dedup_norm(r.get("amount", "")),
               _dedup_norm(r.get("carbs_clean", "")))
        if key in seen:
            continue
        seen.add(key)
        out.append(r)
    return out


_DIGIT_MAP = str.maketrans('ظ ظ،ظ¢ظ£ظ¤ظ¥ظ¦ظ§ظ¨ظ©غ°غ±غ²غ³غ´غµغ¶غ·غ¸غ¹', '01234567890123456789')

def _to_western(s) -> str:
    """طھط­ظˆظٹظ„ ط§ظ„ط£ط±ظ‚ط§ظ… ط§ظ„ط¹ط±ط¨ظٹط©/ط§ظ„ظپط§ط±ط³ظٹط© ط¥ظ„ظ‰ ط¥ظ†ط¬ظ„ظٹط²ظٹط© ظپظ‚ط· (ط¯ظˆظ† طھط؛ظٹظٹط± ط§ظ„ط­ط±ظˆظپ ط§ظ„ط¹ط±ط¨ظٹط©)."""
    return str(s).translate(_DIGIT_MAP).replace('ظ«', '.').replace('ظ¬', ',')

def _clean_carb(val) -> str:
    # ط¹ط±ط¶ ظ…ط­طھظˆظ‰ ط§ظ„ط®ظ„ظٹط© ظƒظ…ط§ ظ‡ظˆطŒ ظ…ط¹ طھط­ظˆظٹظ„ ط§ظ„ط£ط±ظ‚ط§ظ… ط§ظ„ط¹ط±ط¨ظٹط© ط¥ظ„ظ‰ ط¥ظ†ط¬ظ„ظٹط²ظٹط© ظپظ‚ط·.
    # ظ„ط§ ظ†ط­ط°ظپ ط£ظٹ ظ†طµ ظˆظ„ط§ ظ†ط¶ظٹظپ ط£ظٹ ط´ظٹط، â€” ط§ظ„ظ†طµ ط§ظ„ط°ظٹ طھظƒطھط¨ظ‡ ظٹط¸ظ‡ط± ظƒظ…ط§ ظ‡ظˆ.
    if val is None:
        return "â€”"
    t = str(val).strip()
    if t in ("", "nan", "None"):
        return "â€”"
    return _to_western(t)

def _section_type(carbs_clean, section) -> str:
    """طھط­ط¯ظٹط¯ ظ‚ط³ظ… ط§ظ„ط·ط¹ط§ظ… (ط¬ط±ط§ظ…/ط¨ط¯ط§ط¦ظ„) ظ…ظ† ظ†طµ ظ‚ظٹظ…ط© ط§ظ„ظƒط§ط±ط¨طŒ ظ…ط¹ ط§ظ„ط±ط¬ظˆط¹ ظ„ط¹ظ…ظˆط¯ ط§ظ„ظپط¦ط©."""
    cl = str(carbs_clean)
    if "ظ„ظƒظ„ ط¬ط±ط§ظ…" in cl:
        return "grams"
    if "ط¬ط±ط§ظ… ظƒط§ط±ط¨" in cl:
        return "alts"
    s = str(section)
    if "ط¬ط±ط§ظ…" in s:
        return "grams"
    if "ط¨ط¯ط§ط¦ظ„" in s:
        return "alts"
    return ""

def _matches(q_norm: str, food: dict) -> bool:
    return q_norm in food.get("_norm_name", "") or q_norm in food.get("_norm_sec", "")

def _parse_num(val):
    """ط§ط³طھط®ط±ط§ط¬ ط£ظˆظ„ ظ‚ظٹظ…ط© ط±ظ‚ظ…ظٹط© ظ…ظ† ط§ظ„ظ†طµ (ظٹط¯ط¹ظ… ط§ظ„ط£ط±ظ‚ط§ظ… ط§ظ„ط¹ط±ط¨ظٹط© ظˆط§ظ„ط¥ظ†ط¬ظ„ظٹط²ظٹط©)."""
    t = _to_western(val).replace(',', '.')
    m = re.search(r'[-+]?\d+(?:\.\d+)?', t)
    return float(m.group()) if m else None

def _fmt_num(x: float) -> str:
    """طھظ†ط³ظٹظ‚ ظ†ط§طھط¬ ط§ظ„ط­ط³ط§ط¨: ط¥ط²ط§ظ„ط© ط§ظ„ط£طµظپط§ط± ط§ظ„ط²ط§ط¦ط¯ط© ظˆط¹ط±ط¶ظ‡ ط¨ط£ط±ظ‚ط§ظ… ط¥ظ†ط¬ظ„ظٹط²ظٹط©."""
    if x == int(x):
        return str(int(x))
    return f"{x:.2f}".rstrip('0').rstrip('.')


# â•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گ
