def _build_gram_card_html(food: dict) -> str:
    name  = html.escape(str(food.get("name", "")))
    carbs = html.escape(str(food.get("carbs_clean", "â€”")))
    emoji = _food_emoji(str(food.get("name", "")))
    cat   = html.escape(str(food.get("cat_label", "")))
    cat_html = f"<span class='cg-cat'>{cat}</span>" if cat else ""
    return (
        f"<div class='card-gram'>"
        f"<div class='cg-left'>"
        f"<span class='cg-emoji'>{emoji}</span>"
        f"<div class='cg-info'><span class='cg-name'>{name}</span>{cat_html}</div>"
        f"</div>"
        f"<span class='cg-badge'>{carbs}</span>"
        f"</div>"
    )

def _build_gram_card_interactive(food: dict) -> str:
    """ط¨ط·ط§ظ‚ط© آ«ظ„ظƒظ„ ط¬ط±ط§ظ…آ» ظ‚ط§ط¨ظ„ط© ظ„ظ„ط¶ط؛ط·: طھطھط­ظˆظ‘ظ„ ظپظٹ ظ…ظƒط§ظ†ظ‡ط§ ط¥ظ„ظ‰ ظˆط¶ط¹ ط§ظ„ط­ط³ط§ط¨ ط¯ط§ط®ظ„ iframe."""
    name  = html.escape(str(food.get("name", "")))
    carbs = html.escape(str(food.get("carbs_clean", "â€”")))
    emoji = _food_emoji(str(food.get("name", "")))
    cat   = html.escape(str(food.get("cat_label", "")))
    cat_html = f"<span class='cg-cat'>{cat}</span>" if cat else ""
    per_gram = _parse_num(food.get("carbs_clean", ""))
    head = (
        f"<div class='cg-left'>"
        f"<span class='cg-emoji'>{emoji}</span>"
        f"<div class='cg-info'><span class='cg-name'>{name}</span>{cat_html}</div>"
        f"</div>"
        f"<span class='cg-badge'>{carbs}</span>"
    )
    if per_gram is None:
        # ظ„ط§ ظ‚ظٹظ…ط© ط±ظ‚ظ…ظٹط© ظ„ظ„ط­ط³ط§ط¨ â€” طھط¨ظ‚ظ‰ ط¨ط·ط§ظ‚ط© ط¹ط§ط¯ظٹط© ط؛ظٹط± ظ‚ط§ط¨ظ„ط© ظ„ظ„ط¶ط؛ط·
        return f"<div class='card-gram'>{head}</div>"
    pg = f"{per_gram:.6f}".rstrip('0').rstrip('.')
    calc = (
        "<div class='cg-calc'>"
        "<div class='cg-calc-label'>ط£ط¯ط®ظ„ ط§ظ„ظˆط²ظ† (ط¬ظ…)</div>"
        "<input class='cg-w' type='text' inputmode='decimal' "
        "placeholder='ظ…ط«ط§ظ„: 100'>"
        "<button class='cg-btn' type='button'>ط§ط­ط³ط¨</button>"
        "<div class='cg-msg'>ط§ظ„ط±ط¬ط§ط، ط¥ط¯ط®ط§ظ„ ط§ظ„ظˆط²ظ† ط£ظˆظ„ط§ظ‹.</div>"
        "<div class='cg-result'>"
        "<div class='cg-res-label'>ط¥ط¬ظ…ط§ظ„ظٹ ط§ظ„ظƒط±ط¨ظˆظ‡ظٹط¯ط±ط§طھ</div>"
        "<div class='cg-res-num'><span class='cg-res'>â€”</span> "
        "<span class='cg-res-unit'>ط¬ظ… ظƒط±ط¨ظˆظ‡ظٹط¯ط±ط§طھ</span></div>"
        "<button class='cg-add' type='button'>â‍• ط¥ط¶ط§ظپط© ط¥ظ„ظ‰ ظˆط¬ط¨طھظٹ</button>"
        "</div></div>"
    )
    return f"<div class='card-gram' data-pg='{pg}' role='button' tabindex='0'>{head}{calc}</div>"

