    """ظ…ط³طھظ†ط¯ HTML ظƒط§ظ…ظ„ (CSS + JS) ظ„ط´ط¨ظƒط© ط¨ط·ط§ظ‚ط§طھ آ«ظ„ظƒظ„ ط¬ط±ط§ظ…آ» ط§ظ„طھظپط§ط¹ظ„ظٹط© ط¯ط§ط®ظ„ iframe.
    ط§ظ„ط­ط³ط§ط¨ ظٹطھظ… ظپظٹ ط§ظ„ظ…طھطµظپط­ ط¹ظ†ط¯ ط§ظ„ط¶ط؛ط· ط¹ظ„ظ‰ ط²ط± آ«ط§ط­ط³ط¨آ» (ط¯ظˆظ† ط¥ط¹ط§ط¯ط© طھط­ظ…ظٹظ„): ط§ظ„ظˆط²ظ† أ— ظ„ظƒظ„ ط¬ط±ط§ظ…."""
