def _macro_group(label) -> str:
    """ط§ظ„ظ…ط¬ظ…ظˆط¹ط© ط§ظ„ط؛ط°ط§ط¦ظٹط© ط§ظ„ظƒط¨ط±ظ‰ ظ„ط§ط³ظ… ط§ظ„ظپط¦ط© (طھظڈط³طھط®ط¯ظ… ظ„طھظ‚ظٹظٹط¯ ط§ظ„ط¨ط¯ط§ط¦ظ„).
    ط§ظ„ظ†ط´ظˆظٹط§طھ (ط£ط±ط²/ظ…ط¹ظƒط±ظˆظ†ط©/ط®ط¨ط²) طھظڈط¬ظ…ظژظ‘ط¹ ظپظٹ ظ…ط¬ظ…ظˆط¹ط© ظˆط§ط­ط¯ط© 'starch'."""
    return _MACRO_BY_LABEL.get(str(label).strip(), "other")


