def _alt_candidates(grams: list, alts: list) -> list:
    """ظ‚ط§ط¦ظ…ط© ط§ظ„ظ…ط±ط´ط­ظٹظ† ظ„ط¹ط±ط¶ ط§ظ„ط¨ط¯ط§ط¦ظ„ â€” ظƒظ„ظ‡ط§ ظ…ظ† ط¨ظٹط§ظ†ط§طھ Google Sheets ط§ظ„ط­ط§ظ„ظٹط© ظپظ‚ط·.
    ظ†ظˆط¹ط§ظ† ظ…ظ† ط§ظ„ظ…ط±ط´ط­ظٹظ†:
      â€¢ ظ…ط±ط¬ط¹ظٹ (ref): ظ…ظ† ظ‚ط³ظ… آ«ط§ظ„ط¨ط¯ط§ط¦ظ„آ» â€” ظ„ظ‡ ظƒظ…ظٹط© ظ…ط±ط¬ط¹ظٹط© ظ†طµظٹط© (q) ظ…ط«ظ„ آ«ظ†طµظپ ظƒظˆط¨آ»
        ظˆظƒظ…ظٹط© ظƒط±ط¨ظˆظ‡ظٹط¯ط±ط§طھ ظ„طھظ„ظƒ ط§ظ„ط­طµط© (cc). طھظڈط¹ط±ط¶ ط§ظ„ظƒظ…ظٹط© ظƒظ…ط§ ظ‡ظٹ ط¯ظˆظ† ط­ط³ط§ط¨ ظٹط¯ظˆظٹ.
      â€¢ ظ…ط­ط³ظˆط¨ (calc): ظ…ظ† ظ‚ط³ظ… آ«ظ„ظƒظ„ ط¬ط±ط§ظ…آ» â€” ظ„ظ‡ ظ†ط³ط¨ط© ظƒط±ط¨ظˆظ‡ظٹط¯ط±ط§طھ ظ„ظƒظ„ ط¬ط±ط§ظ… (r)طŒ
        ظˆطھظڈط­ط³ط¨ ط§ظ„ظƒظ…ظٹط© ط§ظ„طھظ‚ط¯ظٹط±ظٹط© ط¨ط§ظ„ط¬ط±ط§ظ… ط¹ظ†ط¯ ط§ظ„ط­ط§ط¬ط© (ط§ظ„ظ‡ط¯ظپ أ· r).
    طھظڈط¹ط§ظ„ظژط¬ آ«ط§ظ„ط¨ط¯ط§ط¦ظ„آ» ط£ظˆظ„ط§ظ‹ ظƒظٹ طھظپظˆط² ط§ظ„ظƒظ…ظٹط© ط§ظ„ظ…ط±ط¬ط¹ظٹط© ط¹ظ„ظ‰ ط§ظ„ظ…ط­ط³ظˆط¨ط© ظ„ظ†ظپط³ ط§ظ„ط·ط¹ط§ظ…."""
    out, seen = [], set()
    for f in alts:
        nm = str(f.get("name", "")).strip()
        if not nm or nm in seen:
            continue
        q = str(f.get("amount", "")).strip()
        cc = _parse_num(f.get("carbs_clean", ""))
        if q and q not in ("nan", "None", "") and cc and cc > 0:
            seen.add(nm)
            out.append({"n": nm, "q": q, "cc": cc, "e": _food_emoji(nm),
                        "c": str(f.get("cat_label", "")),
                        "g": _macro_group(f.get("cat_label", ""))})
    for f in grams:
        nm = str(f.get("name", "")).strip()
        if not nm or nm in seen:
            continue
        r = _parse_num(f.get("carbs_clean", ""))
        if r and r > 0:
            seen.add(nm)
            out.append({"n": nm, "r": r, "e": _food_emoji(nm),
                        "c": str(f.get("cat_label", "")),
                        "g": _macro_group(f.get("cat_label", ""))})
    return out


