# ط¬ظ„ط¨ ط§ظ„ط¨ظٹط§ظ†ط§طھ (ظپظˆط±ظٹ ظ…ظ† ط§ظ„ط°ط§ظƒط±ط©)
# â•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گ
GRAMS_FOODS, ALT_FOODS, DATA_VERSION = get_manager().get()
total_all = len(GRAMS_FOODS) + len(ALT_FOODS)

# â”€â”€â”€ ط®ظٹط§ط±ط§طھ ط´ط±ظٹط· ط§ظ„ظپط¦ط§طھ: طھظڈط¨ظ†ظ‰ ظ…ظ† ط§ظ„ط£طµظ†ط§ظپ ط§ظ„ظ…ظˆط¬ظˆط¯ط© ظپط¹ظ„ط§ظ‹طŒ ط¨ط§ظ„طھط±طھظٹط¨ ط§ظ„ظ…ط¹ط±ظ‘ظپ â”€â”€â”€
# ط§ظ„ظ‚ظˆط§ط¹ط¯ ط§ظ„ط«ط§ط¨طھط© ط£ظˆظ„ط§ظ‹طŒ ط«ظ… ط£ظٹ ظپط¦ط© ط¬ط¯ظٹط¯ط© ظ‚ط§ط¯ظ…ط© ظ…ظ† ط¹ظ…ظˆط¯ ط§ظ„ظپط¦ط© ظپظٹ ط§ظ„ط¬ط¯ظˆظ„ (ظ…ظپط§طھظٹط­
# آ«sheet:â€¦آ») طھط¸ظ‡ط± طھظ„ظ‚ط§ط¦ظٹط§ظ‹ ظƒط´ط±ظٹط­ط© ط¯ظˆظ† ط£ظٹ طھط¹ط¯ظٹظ„ ظپظٹ ط§ظ„ظƒظˆط¯.
_ALL_CATS = _CATEGORY_RULES + [("other", "ًںچ½ï¸ڈ", "ط£ط®ط±ظ‰", [])]
_known_keys = {k for (k, _e, _lab, _kw) in _ALL_CATS}
_present_cats = {f.get("_cat") for f in GRAMS_FOODS} | {f.get("_cat") for f in ALT_FOODS}
# طھط³ظ…ظٹط§طھ ط§ظ„ظپط¦ط§طھ ط§ظ„ط¯ظٹظ†ط§ظ…ظٹظƒظٹط© ط§ظ„ظ‚ط§ط¯ظ…ط© ظ…ظ† ط§ظ„ط¬ط¯ظˆظ„ (طھظڈط¤ط®ط° ظƒظ…ط§ ظƒطھط¨ظ‡ط§ ط§ظ„ظ…ط³طھط®ط¯ظ…)
_sheet_cat_labels: dict = {}
for _f in GRAMS_FOODS + ALT_FOODS:
    _k = _f.get("_cat")
    if _k and _k not in _known_keys and _k not in _sheet_cat_labels:
        _sheet_cat_labels[_k] = _f.get("cat_label", _k)
_chip_defs = [(k, e, lab) for (k, e, lab, _kw) in _ALL_CATS if k in _present_cats]
_chip_defs += [(k, "ًںڈ·ï¸ڈ", _sheet_cat_labels[k]) for k in sorted(_sheet_cat_labels)]
CAT_OPTIONS = ["ط§ظ„ظƒظ„"] + [f"{e} {lab}" for (k, e, lab) in _chip_defs]
CHIP_TO_KEY = {f"{e} {lab}": k for (k, e, lab) in _chip_defs}
CHIP_TO_KEY["ط§ظ„ظƒظ„"] = None


# â”€â”€â”€ ط¯ظˆط§ظ„ ط±ط³ظ… ط§ظ„ط¨ط·ط§ظ‚ط§طھ â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
def _render_card_grid(cards: list):
    for i in range(0, len(cards), 2):
        cols = st.columns(2, gap="small")
        for j, col in enumerate(cols):
            idx = i + j
            if idx >= len(cards):
                break
            with col:
                st.markdown(cards[idx], unsafe_allow_html=True)


def render_cards(section: str, foods: list, version: int, search: str, cat: str):
    """ط±ط³ظ… ط¨ط·ط§ظ‚ط§طھ ط§ظ„ط£ط·ط¹ظ…ط© ظپظٹ ط´ط¨ظƒط© ظ…ط³ط·ظ‘ط­ط© (ط¯ظˆظ† طھط¬ظ…ظٹط¹ ط­ط³ط¨ ط§ظ„ظپط¦ط©)."""
    html_list = _get_card_html_cache(section, foods, version, search, cat)
    _render_card_grid(html_list)


