# â•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گ
# ظ‚ط³ظ… ط§ظ„ط¨ط­ط« ط¨ط§ظ„ط°ظƒط§ط، ط§ظ„ط§طµط·ظ†ط§ط¹ظٹ (ظ…ط¹ط²ظˆظ„ طھظ…ط§ظ…ط§ظ‹: ط£ظٹ ط®ط·ط£ ظپظٹظ‡ ظ„ط§ ظٹط¤ط«ط± ط¹ظ„ظ‰ ط¨ظ‚ظٹط© ط§ظ„ظ…ظˆظ‚ط¹)
# â•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گâ•گ
# â”€â”€ Feature Flag: طھظپط¹ظٹظ„/طھط¹ط·ظٹظ„ ظ…ظٹط²ط© ط§ظ„ط¨ط­ط« ط¨ط§ظ„ط°ظƒط§ط، ط§ظ„ط§طµط·ظ†ط§ط¹ظٹ â”€â”€
# ط؛ظٹظ‘ط± ط§ظ„ظ‚ظٹظ…ط© ط¥ظ„ظ‰ True ظ„ط¥ط¹ط§ط¯ط© طھظپط¹ظٹظ„ ط§ظ„ظ…ظٹط²ط© ط¨ط§ظ„ظƒط§ظ…ظ„ (ظ„ط§ ط­ط§ط¬ط© ظ„ط£ظٹ طھط¹ط¯ظٹظ„ ط¢ط®ط±).
# ط¹ظ†ط¯ False: طھط¨ظ‚ظ‰ ط§ظ„ط¨ط·ط§ظ‚ط© ط¸ط§ظ‡ط±ط© ط¨ظ†ظپط³ ط§ظ„طھطµظ…ظٹظ… ظ„ظƒظ† ط§ظ„ط­ظ‚ظˆظ„ ظˆط§ظ„ط£ط²ط±ط§ط± ظ…ط¹ط·ظ„ط©طŒ
# ظˆطھط¸ظ‡ط± ط±ط³ط§ظ„ط© آ«ظ‡ط°ظ‡ ط§ظ„ظ…ظٹط²ط© ط؛ظٹط± ظ…ظپط¹ظ„ط© ط­ط§ظ„ظٹظ‹ط§آ». ظ„ط§ ظٹظڈط­ط°ظپ ط£ظٹ ظƒظˆط¯ ط£ظˆ ط¥ط¹ط¯ط§ط¯ ط£ظˆ ظ…ظپطھط§ط­.
AI_SEARCH_ENABLED = False
def _ai_actions_doc(text: str) -> str:
    """ظ…ط³طھظ†ط¯ iframe طµط؛ظٹط± ظ„ط²ط±ظ‘ظٹ آ«ظ†ط³ط®آ» ظˆآ«ظ…ط´ط§ط±ظƒط©آ» â€” ظٹط¹ظ…ظ„ط§ظ† ط¨ظ†ظ‚ط±ط© ظ…ط¨ط§ط´ط±ط© ظ…ظ† ط§ظ„ظ…ط³طھط®ط¯ظ…."""
    import json as _json
    payload = _json.dumps(text).replace("<", "\\u003c")
    doc = """<!doctype html><html lang='ar' dir='rtl'><head><meta charset='utf-8'>
<style>
@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@700;800&display=swap');
*{box-sizing:border-box;margin:0;padding:0;font-family:'Cairo',-apple-system,'Segoe UI',sans-serif;}
body{background:transparent;display:flex;gap:10px;justify-content:flex-start;padding:2px;}
button{flex:1;max-width:190px;cursor:pointer;border-radius:12px;padding:10px 12px;font-weight:800;
  font-size:0.9rem;border:1.5px solid #cddfe2;background:#fff;color:#3e6e7e;transition:all .15s;}
button:hover{background:#eaf3f4;border-color:#3e6e7e;}
button:active{transform:translateY(1px);}
.done{background:#e7f4ec !important;border-color:#4f7340 !important;color:#3f6a33 !important;}
</style></head><body>
<button id='cp'>\uD83D\uDCCB \u0646\u0633\u062E</button>
<button id='sh'>\uD83D\uDD17 \u0645\u0634\u0627\u0631\u0643\u0629</button>
<script>
var T=__PAYLOAD__;
function copy(){
  try{ if(navigator.clipboard&&navigator.clipboard.writeText){return navigator.clipboard.writeText(T);} }catch(e){}
  return new Promise(function(res){var ta=document.createElement('textarea');ta.value=T;
    ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.focus();ta.select();
    try{document.execCommand('copy');}catch(e){}document.body.removeChild(ta);res();});
}
var cp=document.getElementById('cp'), sh=document.getElementById('sh');
cp.addEventListener('click',function(){copy().then(function(){cp.textContent='\u2713 \u062A\u0645 \u0627\u0644\u0646\u0633\u062E';
  cp.classList.add('done');setTimeout(function(){cp.textContent='\uD83D\uDCCB \u0646\u0633\u062E';cp.classList.remove('done');},1600);});});
sh.addEventListener('click',function(){
  if(navigator.share){navigator.share({text:T}).catch(function(){});}
  else{copy().then(function(){sh.textContent='\u2713 \u062A\u0645 \u0627\u0644\u0646\u0633\u062E \u0644\u0644\u0645\u0634\u0627\u0631\u0643\u0629';
    sh.classList.add('done');setTimeout(function(){sh.textContent='\uD83D\uDD17 \u0645\u0634\u0627\u0631\u0643\u0629';sh.classList.remove('done');},1600);});}
});
</script></body></html>"""
    return doc.replace("__PAYLOAD__", payload)


def render_ai_section():
    """ظ‚ط³ظ… ط§ظ„ط¨ط­ط« ط¨ط§ظ„ط°ظƒط§ط، ط§ظ„ط§طµط·ظ†ط§ط¹ظٹ (Gemini) â€” ط§ظ…طھط¯ط§ط¯ ظ„ط®ط§ظ†ط© ط§ظ„ط¨ط­ط« ط¹ظ† ط§ظ„ط·ط¹ط§ظ….

    طھطµظ…ظٹظ… ط¨ط³ظٹط·: طµظ†ط¯ظˆظ‚ ط¥ط¯ط®ط§ظ„ ظ…ط·ط§ط¨ظ‚ ظ„ط®ط§ظ†ط© ط§ظ„ط¨ط­ط« + ط£ظٹظ‚ظˆظ†طھظٹ ظƒط§ظ…ظٹط±ط§/ط±ظپط¹ طµظˆط±ط© + ط²ط± ط¥ط±ط³ط§ظ„طŒ
    ط«ظ… طھط¸ظ‡ط± ط§ظ„ط¥ط¬ط§ط¨ط© ظپظٹ ط¨ط·ط§ظ‚ط© ط£ظ†ظٹظ‚ط© ط£ط³ظپظ„ظ‡ ظ…ط¨ط§ط´ط±ط©. ظ„ط§ ظ…ط­ط§ط¯ط«ط§طھ ظˆظ„ط§ ط³ط¬ظ„ ظˆظ„ط§ ظپظ‚ط§ط¹ط§طھ ط¯ط±ط¯ط´ط©.
    ظƒظ„ ط§ظ„ط§ط³طھظٹط±ط§ط¯ط§طھ ظƒط³ظˆظ„ط© (lazy) ظ„ظ„ط­ظپط§ط¸ ط¹ظ„ظ‰ ط³ط±ط¹ط© ط§ظ„ط¥ظ‚ظ„ط§ط¹طŒ ظˆط§ظ„ظ‚ط³ظ… ظ…ط¹ط²ظˆظ„ طھظ…ط§ظ…ط§ظ‹: ط£ظٹ ظپط´ظ„
    ظپظٹ ط§ظ„ظ…ظپطھط§ط­/ظ‚ط§ط¹ط¯ط© ط§ظ„ط¨ظٹط§ظ†ط§طھ/ط§ظ„ط´ط¨ظƒط© ظٹظڈط¸ظ‡ط± ط±ط³ط§ظ„ط© ظ„ط·ظٹظپط© ظپظ‚ط· ظˆظٹط¨ظ‚ظ‰ ط¨ط§ظ‚ظٹ ط§ظ„ظ…ظˆظ‚ط¹ ظٹط¹ظ…ظ„.
    """
    # â”€â”€ ط§ظ„ظ…ظٹط²ط© ظ…ط¹ط·ظ„ط© ظ…ط¤ظ‚طھط§ظ‹ (Feature Flag): ظ†ظپط³ ط§ظ„ط¨ط·ط§ظ‚ط© ظ„ظƒظ† ظƒظ„ ط§ظ„ط¹ظ†ط§طµط± Disabled â”€â”€
    if not AI_SEARCH_ENABLED:
        with st.container(key="ai_box"):
            c_q, c_cam, c_send = st.columns(3, vertical_alignment="center")
            with c_q:
                st.text_input(
                    "ط³ط¤ط§ظ„ظƒ", placeholder="ط§ط³ط£ظ„ ط¹ظ† ط£ظٹ ط·ط¹ط§ظ…...",
                    label_visibility="collapsed", key="ai_q_off", disabled=True)
            with c_cam:
                with st.container(key="ai_cam_row"):
                    st.file_uploader(
                        "ط¥ط¶ط§ظپط© طµظˆط±ط©",
                        type=["png", "jpg", "jpeg", "webp"],
                        label_visibility="collapsed", key="ai_cam_off", disabled=True)
            with c_send:
                st.button("â‍¤", key="ai_send_off", disabled=True)
        st.markdown(
            "<div class='ai-note'>ظ‡ط°ظ‡ ط§ظ„ظ…ظٹط²ط© ط؛ظٹط± ظ…ظپط¹ظ„ط© ط­ط§ظ„ظٹظ‹ط§طŒ ظˆط³طھطھظˆظپط± ظ‚ط±ظٹط¨ظ‹ط§.</div>",
            unsafe_allow_html=True)
        return

    import uuid as _uuid
    import base64 as _b64
    from datetime import datetime as _dt, timedelta as _td, date as _date

    try:
        from services import config as _cfg
        from services import db_service as _db
        from services import ai_service as _ai
        from services.ai_service import AIError as _AIError
    except Exception:
        logging.exception("AI services import failed")
        st.markdown(
            "<div class='ai-note'>ظ‚ط³ظ… ط§ظ„ط°ظƒط§ط، ط§ظ„ط§طµط·ظ†ط§ط¹ظٹ ط؛ظٹط± ظ…طھط§ط­ ط­ط§ظ„ظٹط§ظ‹. ط¨ط§ظ‚ظٹ ط§ظ„ظ…ظˆظ‚ط¹ ظٹط¹ظ…ظ„ ط¨ط´ظƒظ„ ط·ط¨ظٹط¹ظٹ.</div>",
            unsafe_allow_html=True)
        return

    if not _ai.is_available():
        st.markdown(
            "<div class='ai-note'>ظ…ظٹط²ط© ط§ظ„ط°ظƒط§ط، ط§ظ„ط§طµط·ظ†ط§ط¹ظٹ ط؛ظٹط± ظ…ظڈظ‡ظٹظ‘ط£ط© ط­ط§ظ„ظٹط§ظ‹. ط¨ط§ظ‚ظٹ ط§ظ„ظ…ظˆظ‚ط¹ ظٹط¹ظ…ظ„ ط¨ط´ظƒظ„ ط·ط¨ظٹط¹ظٹ.</div>",
            unsafe_allow_html=True)
        return

    # ظ‚ط§ط¹ط¯ط© ط§ظ„ط¨ظٹط§ظ†ط§طھ ط§ط®طھظٹط§ط±ظٹط© â€” طھظڈط³طھط®ط¯ظ… ظپظ‚ط· ظ„طھط·ط¨ظٹظ‚ ط§ظ„ط­ط¯ظˆط¯ ط§ظ„ظٹظˆظ…ظٹط© ظ„ظƒظ„ ظ…ط³طھط®ط¯ظ….
    if "ai_db_ok" not in st.session_state:
        st.session_state["ai_db_ok"] = _db.db_available()
    db_ok = st.session_state["ai_db_ok"]

    MSG_LIMIT = _cfg.DAILY_MSG_LIMIT
    IMG_LIMIT = _cfg.DAILY_IMG_LIMIT
    today = _date.today()

    # â”€â”€ ظ‡ظˆظٹط© ظ…ط¬ظ‡ظˆظ„ط© ط¹ط¨ط± ظƒظˆظƒظٹ (ظ„ط­ط¯ظˆط¯ ط§ظ„ط§ط³طھط®ط¯ط§ظ… ظپظ‚ط·) â€” ظ„ط§ طھظڈط¹ط·ظ‘ظ„ ط§ظ„ظˆط§ط¬ظ‡ط© ط¥ظ† ظ„ظ… طھط¬ظ‡ط² ط¨ط¹ط¯ â”€â”€
    def _resolve_uid():
        if not db_ok:
            return None
        u = st.session_state.get("ai_uid")
        if u:
            return u
        try:
            import extra_streamlit_components as stx
            cm = stx.CookieManager(key="carbai_cm")
            found = (cm.get_all() or {}).get("carbai_uid")
            if found:
                st.session_state["ai_uid"] = found
                return found
            if st.session_state.get("_ai_cookie_ready"):
                nu = "u_" + _uuid.uuid4().hex
                cm.set("carbai_uid", nu, expires_at=_dt.now() + _td(days=365))
                st.session_state["ai_uid"] = nu
                return nu
            st.session_state["_ai_cookie_ready"] = True
        except Exception:
            pass
        # ظ…ط¤ظ‚طھط§ظ‹ (ظ„ظ‡ط°ظ‡ ط§ظ„ط¬ظ„ط³ط©) ط­طھظ‰ طھط¬ظ‡ط² ط§ظ„ظƒظˆظƒظٹ â€” طھط¨ظ‚ظ‰ ط§ظ„ط­ط¯ظˆط¯ ظپط¹ظ‘ط§ظ„ط©
        return st.session_state.setdefault("ai_uid_tmp", "s_" + _uuid.uuid4().hex)

    uid = _resolve_uid()
    n = st.session_state.get("ai_nonce", 0)

    # â”€â”€ طµظ†ط¯ظˆظ‚ ط§ظ„ط¥ط¯ط®ط§ظ„ (ظ…ط·ط§ط¨ظ‚ ظ„ط®ط§ظ†ط© ط§ظ„ط¨ط­ط« ط¹ظ† ط§ظ„ط·ط¹ط§ظ…): ط³ط·ط± ظˆط§ط­ط¯ = ط­ظ‚ظ„ ط§ظ„ظ†طµ + ط²ط± ط§ظ„ظƒط§ظ…ظٹط±ط§ ظٹط³ط§ط±ظ‡ + ط²ط± ط§ظ„ط¥ط±ط³ط§ظ„ â”€â”€
    cam_val = None
    up_val = None
    with st.container(key="ai_box"):
        c_q, c_cam, c_send = st.columns(3, vertical_alignment="center")
        with c_q:
            q = st.text_input(
                "ط³ط¤ط§ظ„ظƒ", placeholder="ط§ط³ط£ظ„ ط¹ظ† ط£ظٹ ط·ط¹ط§ظ…...",
                label_visibility="collapsed", key=f"ai_q_{n}",
            )
        with c_cam:
            with st.container(key="ai_cam_row"):
                cam_val = st.file_uploader(
                    "ط¥ط¶ط§ظپط© طµظˆط±ط©",
                    type=["png", "jpg", "jpeg", "webp"],
                    label_visibility="collapsed", key=f"ai_cam_{n}")
        with c_send:
            sent = st.button("â‍¤", key=f"ai_send_{n}")

    img_up = cam_val or up_val
    if img_up is not None:
        st.markdown(
            "<div class='ai-attached'>âœ“ طھظ… ط¥ط±ظپط§ظ‚ طµظˆط±ط© â€” ط§ط¶ط؛ط· ط²ط± ط§ظ„ط¥ط±ط³ط§ظ„ ظ„طھط­ظ„ظٹظ„ظ‡ط§.</div>",
            unsafe_allow_html=True)

    if sent:
        text = (q or "").strip()
        has_img = img_up is not None
        if not text and not has_img:
            st.warning("ط§ظƒطھط¨ ط³ط¤ط§ظ„ط§ظ‹ ط£ظˆ ط§ط±ظپط¹ طµظˆط±ط© ط£ظˆظ„ط§ظ‹.")
        else:
            blocked = False
            # ظ‚ط±ط§ط،ط© ط§ظ„ط§ط³طھظ‡ظ„ط§ظƒ ط§ظ„ظٹظˆظ…ظٹ: ظ‚ط§ط¹ط¯ط© ط§ظ„ط¨ظٹط§ظ†ط§طھ ط¥ظ† طھظˆظپظ‘ط±طھطŒ ظˆط¥ظ„ط§ ط¹ط¯ظ‘ط§ط¯ ط§ظ„ط¬ظ„ط³ط©
            # (طھط¨ظ‚ظ‰ ط§ظ„ط­ط¯ظˆط¯ ظپط¹ظ‘ط§ظ„ط© ط¯ط§ط¦ظ…ط§ظ‹ ط­طھظ‰ ط¹ظ†ط¯ طھط¹ط·ظ‘ظ„ ظ‚ط§ط¹ط¯ط© ط§ظ„ط¨ظٹط§ظ†ط§طھ).
            used_msg, used_img = 0, 0
            got_from_db = False
            if db_ok and uid:
                try:
                    used_msg, used_img = _db.get_usage(uid, today)
                    got_from_db = True
                except Exception:
                    got_from_db = False
            if not got_from_db:
                _sess_usage = st.session_state.get(
                    f"ai_usage_{today}", {"msg": 0, "img": 0})
                used_msg, used_img = _sess_usage["msg"], _sess_usage["img"]
            if used_msg >= MSG_LIMIT:
                st.warning(f"ظ„ظ‚ط¯ ظˆطµظ„طھ ط¥ظ„ظ‰ ط§ظ„ط­ط¯ ط§ظ„ظٹظˆظ…ظٹ ط§ظ„ظ…ط³ظ…ظˆط­ ط¨ظ‡ ظ…ظ† ط§ظ„ط£ط³ط¦ظ„ط© ({MSG_LIMIT}). ظٹظ…ظƒظ†ظƒ ط§ظ„ظ…طھط§ط¨ط¹ط© ط؛ط¯ط§ظ‹. ًںŒ™")
                blocked = True
            elif has_img and used_img >= IMG_LIMIT:
                st.warning(f"ظ„ظ‚ط¯ ظˆطµظ„طھ ط¥ظ„ظ‰ ط§ظ„ط­ط¯ ط§ظ„ظٹظˆظ…ظٹ ط§ظ„ظ…ط³ظ…ظˆط­ ط¨ظ‡ ظ…ظ† ط§ظ„طµظˆط± ({IMG_LIMIT}). ظٹظ…ظƒظ†ظƒ ط§ظ„ظ…طھط§ط¨ط¹ط© ط؛ط¯ط§ظ‹. ًںŒ™")
                blocked = True

            if not blocked:
                # طھط¬ظ‡ظٹط² ط§ظ„طµظˆط±ط© (طھطµط؛ظٹط± ظ„ظ„ط£ط¯ط§ط،) + ظ…ط¹ط§ظٹظ†ط© ظ…طµط؛ظ‘ط±ط©
                img_bytes = None
                img_mime = None
                preview_uri = None
                if has_img:
                    try:
                        from PIL import Image
                        import io
                        raw = img_up.getvalue()
                        im = Image.open(io.BytesIO(raw)).convert("RGB")
                        w, h = im.size
                        mx = max(w, h)
                        if mx > 1024:
                            s = 1024 / mx
                            im = im.resize((int(w * s), int(h * s)))
                        buf = io.BytesIO()
                        im.save(buf, format="JPEG", quality=85)
                        img_bytes = buf.getvalue()
                        img_mime = "image/jpeg"
                        pim = im.copy()
                        pw, ph2 = pim.size
                        pmx = max(pw, ph2)
                        if pmx > 360:
                            ps = 360 / pmx
                            pim = pim.resize((int(pw * ps), int(ph2 * ps)))
                        pbuf = io.BytesIO()
                        pim.save(pbuf, format="JPEG", quality=80)
                        preview_uri = "data:image/jpeg;base64," + _b64.b64encode(pbuf.getvalue()).decode()
                    except Exception:
                        img_bytes = img_up.getvalue()
                        img_mime = getattr(img_up, "type", None) or "image/jpeg"

                # ظ…ط¤ط´ط± طھط­ظ…ظٹظ„ ط£ظ†ظٹظ‚ ط£ط«ظ†ط§ط، ط§ظ„طھط­ظ„ظٹظ„
                ph = st.empty()
                ph.markdown(
                    "<div class='ai-loading'><span class='ai-load-ico'>ًں”چ</span> "
                    + ("ط¬ط§ط±ظچ طھط­ظ„ظٹظ„ ط§ظ„طµظˆط±ط©â€¦" if has_img else "ط¬ط§ط±ظچ ط§ظ„ط¨ط­ط« ط¹ظ† ط¥ط¬ط§ط¨طھظƒâ€¦")
                    + "</div>",
                    unsafe_allow_html=True,
                )
                reply = None
                err = None
                try:
                    reply = _ai.generate_reply([], text, img_bytes, img_mime)
                except _AIError as e:
                    err = str(e)
                finally:
                    ph.empty()

                if err:
                    st.error(err)
                else:
                    inc_in_db = False
                    if db_ok and uid:
                        try:
                            _db.increment_usage(uid, today, messages=1, images=1 if has_img else 0)
                            inc_in_db = True
                        except Exception:
                            inc_in_db = False
                    if not inc_in_db:
                        _su = st.session_state.get(
                            f"ai_usage_{today}", {"msg": 0, "img": 0})
                        _su["msg"] += 1
                        if has_img:
                            _su["img"] += 1
                        st.session_state[f"ai_usage_{today}"] = _su
                    st.session_state["ai_last_answer"] = reply
                    st.session_state["ai_last_img"] = preview_uri
                    st.session_state["ai_nonce"] = n + 1
                    st.rerun()

    # â”€â”€ ط¨ط·ط§ظ‚ط© ط§ظ„ط¥ط¬ط§ط¨ط© (ط£ط³ظپظ„ ط§ظ„طµظ†ط¯ظˆظ‚ ظ…ط¨ط§ط´ط±ط©) â”€â”€
    ans = st.session_state.get("ai_last_answer")
    if ans:
        ans = _ai._sanitize_text(ans)
        with st.container(key="ai_answer"):
            prev = st.session_state.get("ai_last_img")
            if prev:
                st.markdown(
                    f"<div class='ai-thumb-wrap'><img class='ai-thumb' src='{prev}' alt='طµظˆط±ط© ط§ظ„ط·ط¹ط§ظ…'/></div>",
                    unsafe_allow_html=True)
            st.markdown(ans)
            try:
                st.iframe(_ai_actions_doc(ans), height=62)
            except Exception:
                logging.exception("AI actions bar failed")
        if st.button("â‍• ط³ط¤ط§ظ„ ط¬ط¯ظٹط¯", key="ai_newq"):
            st.session_state.pop("ai_last_answer", None)
            st.session_state.pop("ai_last_img", None)
            st.session_state["ai_nonce"] = st.session_state.get("ai_nonce", 0) + 1
            st.rerun()


